//A        private static int GetLeftMin(List<Sprite> sprites) {            var leftMin = Int32.MaxValue;            sprites.Where(s => s.Left < leftMin).Do(s => leftMin = s.Left);            return leftMin;        }        private static int GetTopMin(List<Sprite> sprites) {            var topMin = Int32.MaxValue;            sprites.Where(s => s.Top < topMin).Do(s => topMin = s.Top);            return topMin;        }        private static int GetRightMax(List<Sprite> sprites) {            var rightMax = 0;            sprites.Where(s => s.Right > rightMax).Do(s => rightMax = s.Right);            return rightMax;        }        private static int GetBottomMax(List<Sprite> sprites) {            var bottomMax = 0;            sprites.Where(s => s.Bottom > bottomMax).Do(s => bottomMax = s.Bottom);            return bottomMax;        }//B        private static Point GetSpritesMin(List<Sprite> sprites) {            var min = new Point(Int32.MaxValue, Int32.MaxValue);            sprites.ForEach(s => {                if (s.Left < min.X) min.X = s.Left;                if (s.Top < min.Y) min.Y = s.Top;            });            return min;        }        private static Point GetSpritesMax(List<Sprite> sprites) {            var max = new Point(0, 0);            sprites.ForEach(s => {                if (s.Right > max.X) max.X = s.Right;                if (s.Bottom > max.Y) max.Y = s.Bottom;            });            return max;        }//C		private static Rectangle GetSpritesRect(List<Sprite> sprites) {            var left = Int32.MaxValue;            var top = Int32.MaxValue;            var right = 0;            var bottom = 0;            sprites.ForEach(s => {                if (s.Left < left) left = s.Left;                if (s.Top < top) top = s.Top;                if (s.Right > right) right = s.Right;                if (s.Bottom > bottom) bottom = s.Bottom;            });            return new Rectangle().FromLRTB(left, right, top, bottom);        }//D        private static Rectangle GetSpritesRect(List<Sprite> sprites) {            var rect = sprites.FirstOrDefault().Bounds;            // get min            sprites.ForEach(s => {                if (s.Left < rect.Left) rect.X = s.Left;                if (s.Top < rect.Top) rect.Y = s.Top;            });            // get max            sprites.ForEach(s => {                if (s.Right > rect.Right) rect.Width = s.Right - rect.Left;                if (s.Bottom > rect.Bottom) rect.Height = s.Bottom - rect.Top;            });            return rect;        }